// 节目固定播出顺序（按时段），编成表/上一首下一首都按这个排
export const PROGRAM_ORDER = [
  'squirrel-morning',
  'animal-news',
  'bear-night',
  'fox-cafe',
] as const;

// 已囤内容的最大 Day（内容尚未覆盖的 Day 回落到这个天数）
export function getMaxRadioDay(): number {
  return RADIO_EPISODES.reduce((m, e) => Math.max(m, e.day), 1);
}

// 把用户当前 Day 夹到已有内容范围内（Day 1..maxDay）
export function clampRadioDay(day: number): number {
  const max = getMaxRadioDay();
  if (!Number.isFinite(day) || day < 1) return 1;
  return Math.min(day, max);
}

// 某个 Day 的 4 档节目（完整对象），按播出时段排序
export function getEpisodesForDay(day: number): RadioEpisode[] {
  const d = clampRadioDay(day);
  return RADIO_EPISODES.filter((e) => e.day === d).sort(
    (a, b) => PROGRAM_ORDER.indexOf(a.program as never) - PROGRAM_ORDER.indexOf(b.program as never),
  );
}

// 轻量元数据（不含 subtitles/vocab），供首页/编成表/上下首用
export function toCard(e: RadioEpisode): RadioCard {
  return {
    id: e.id,
    program: e.program,
    title: e.title,
    titleZh: e.titleZh,
    host: e.host,
    hostEmoji: e.hostEmoji,
    level: e.level,
    duration: e.duration,
    scheduleTime: e.scheduleTime,
    coverColor: e.coverColor,
    category: e.category,
    day: e.day,
  };
}

// 某个 Day 的 4 档元数据（轻量，约 2KB），/api/radio/episodes 用
export function getEpisodesByDay(day: number): RadioCard[] {
  return getEpisodesForDay(day).map(toCard);
}

// 已解锁的全部往期（Day 1..当前Day）轻量元数据，按 day 降序（新→旧）供往期库/回看用
export function getEpisodesUpToDay(day: number): RadioCard[] {
  const max = clampRadioDay(day);
  return RADIO_EPISODES
    .filter((e) => e.day <= max)
    .sort(
      (a, b) =>
        b.day - a.day ||
        PROGRAM_ORDER.indexOf(a.program as never) - PROGRAM_ORDER.indexOf(b.program as never),
    )
    .map(toCard);
}

// 单期完整数据（含 subtitles/vocab），/api/radio/episode/[id] 与播放器 SSR 用
// 日播 + 访谈档都按 id 全局查（播放器路由不受 day 门控）
export function getEpisodeById(id: string): RadioEpisode | null {
  return RADIO_EPISODES.find((e) => e.id === id)
    ?? INTERVIEW_EPISODES.find((e) => e.id === id)
    ?? null;
}

// 全部 id，供 generateStaticParams（含访谈档）
export function getEpisodeSlugs(): string[] {
  return [...RADIO_EPISODES, ...INTERVIEW_EPISODES].map((e) => e.id);
}

// 访谈专区 10 期轻量元数据（按 day 升序），/api/radio/interview 与列表页用
// 与日播完全隔离：不进编成表、不受 clampRadioDay 门控
export function getInterviewEpisodes(): RadioCard[] {
  return [...INTERVIEW_EPISODES].sort((a, b) => a.day - b.day).map(toCard);
}

// 首页 "正在播放"：按当前钟点挑当天最贴近的一档（返回轻量元数据）
export function getNowPlaying(day: number): RadioCard {
  const list = getEpisodesForDay(day);
  const nowHm = new Date().getHours() * 60 + new Date().getMinutes();
  let pick = list[0];
  for (const ep of list) {
    const [h, m] = ep.scheduleTime.split(':').map(Number);
    if (h * 60 + m <= nowHm) pick = ep;
  }
  return toCard(pick);
}

